-- Booking service schema is added in a later task.
CREATE TABLE IF NOT EXISTS bookings (id UUID PRIMARY KEY, customer_id UUID NOT NULL, driver_id UUID, payment_id UUID, pickup_lat DOUBLE PRECISION NOT NULL CHECK (pickup_lat BETWEEN -90 AND 90), pickup_lng DOUBLE PRECISION NOT NULL CHECK (pickup_lng BETWEEN -180 AND 180), pickup_address VARCHAR(255), dest_lat DOUBLE PRECISION NOT NULL CHECK (dest_lat BETWEEN -90 AND 90), dest_lng DOUBLE PRECISION NOT NULL CHECK (dest_lng BETWEEN -180 AND 180), dest_address VARCHAR(255), distance_km NUMERIC(10,2) NOT NULL CHECK (distance_km >= 0), fare BIGINT NOT NULL CHECK (fare >= 0), status VARCHAR(30) NOT NULL DEFAULT 'PAYMENT_PENDING' CHECK (status IN ('PAYMENT_PENDING','PAYMENT_FAILED','SEARCHING_DRIVER','DRIVER_ASSIGNED','NO_DRIVER_FOUND','CANCELED','COMPLETED')), assigned_at TIMESTAMPTZ, canceled_at TIMESTAMPTZ, cancel_reason VARCHAR(200), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_bk_customer ON bookings(customer_id, created_at); CREATE INDEX IF NOT EXISTS ix_bk_driver ON bookings(driver_id); CREATE INDEX IF NOT EXISTS ix_bk_payment ON bookings(payment_id); CREATE INDEX IF NOT EXISTS ix_bk_status ON bookings(status, created_at);
CREATE TABLE IF NOT EXISTS booking_offers (id UUID PRIMARY KEY, booking_id UUID NOT NULL, driver_id UUID NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','ACCEPTED','REJECTED','SUPERSEDED')), expires_at TIMESTAMPTZ NOT NULL, responded_at TIMESTAMPTZ, reject_reason VARCHAR(200), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (booking_id, driver_id));
CREATE INDEX IF NOT EXISTS ix_bo_booking ON booking_offers(booking_id, status); CREATE INDEX IF NOT EXISTS ix_bo_driver ON booking_offers(driver_id, status, expires_at);
CREATE TABLE IF NOT EXISTS idempotency_keys (id UUID PRIMARY KEY, key VARCHAR(120) NOT NULL, user_id UUID NOT NULL, endpoint VARCHAR(120) NOT NULL DEFAULT 'POST /bookings', request_hash CHAR(64) NOT NULL, response_code INT NOT NULL, response_body JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ NOT NULL, UNIQUE (user_id, endpoint, key));
CREATE INDEX IF NOT EXISTS ix_idem_user ON idempotency_keys(user_id); CREATE INDEX IF NOT EXISTS ix_idem_expires ON idempotency_keys(expires_at);
